import os
import glob
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
import re
from tqdm import tqdm
from scipy.stats import pearsonr

# --- USER CONFIGURATION ---
BIDS_DIR = os.environ.get("MEMORIA_ROOT", ".")
BIDS_TASK_NAME = "forgetexp" # The task name in the BIDS filenames

# Point to the CSV file generated by your FIRST script (the one with broad conditions)
ID_RESULTS_CSV = "./id_analysis_results_by_condition/group_id_full_results_by_condition.csv"

# --- DEFINE WHAT TO LOOP OVER ---
TASK_PHASES_TO_ANALYZE = ["Enc", "Face", "Recall", "Feedback"]
ROIS_TO_ANALYZE = ["V1", "hV4", "LOIT", "phc", "hippocampus"]
BEHAVIORAL_METRICS = ["Accuracy", "Guess_Rate", "Sure_Rate"]

# Output directory for these new results
OUTPUT_DIR = "./id_vs_behavior_comprehensive_correlation"
os.makedirs(OUTPUT_DIR, exist_ok=True)

# Set a p-value threshold for generating individual scatter plots
SIGNIFICANCE_THRESHOLD = 0.05
# --- END OF CONFIGURATION ---

def calculate_behavioral_metrics_for_subject(subject_id, session_id="1"):
    """
    Parses a subject's events.tsv file to calculate overall behavioral metrics FOR RECALL TRIALS.
    Behavior is always calculated from the recall phase, as that's where the relevant actions occur.
    """
    try:
        events_file = os.path.join(
            BIDS_DIR, f"sub-{subject_id}", f"ses-{session_id}", "func",
            f"sub-{subject_id}_ses-{session_id}_task-{BIDS_TASK_NAME}_events.tsv"
        )
        df = pd.read_csv(events_file, sep='\t')
    except FileNotFoundError:
        print(f"Warning: Events file not found for sub-{subject_id}. Skipping.")
        return None

    # Parse the detailed trial_type string
    pattern = re.compile(r'(\w+?)(\d+)_(\w+?)(?:_(\w+))?$')
    parsed_data = df['trial_type'].str.extract(pattern)
    parsed_data.columns = ['Task_Phase', 'ItemID', 'Confidence', 'Accuracy']
    
    # We are interested in behavior during the 'Recall' phase
    recall_df = parsed_data[parsed_data['Task_Phase'] == 'Recall'].copy()
    recall_df = recall_df[recall_df['Confidence'] != 'noResp']
    
    if recall_df.empty:
        return None
        
    total_trials = len(recall_df)
    
    # Calculate metrics
    accuracy = (recall_df['Accuracy'] == 'correct').sum() / total_trials
    guess_rate = (recall_df['Confidence'] == 'guess').sum() / total_trials
    sure_rate = (recall_df['Confidence'] == 'sure').sum() / total_trials
    
    return {
        "Subject": subject_id,
        "Accuracy": accuracy,
        "Guess_Rate": guess_rate,
        "Sure_Rate": sure_rate
    }


def main():
    """
    Main function to run the comprehensive between-subjects correlation analysis.
    """
    print("--- Starting Comprehensive Between-Subjects ID vs. Behavior Correlation Analysis ---")

    # 1. Load the pre-computed Intrinsic Dimensionality results
    if not os.path.exists(ID_RESULTS_CSV):
        print(f"FATAL ERROR: ID results file not found at {ID_RESULTS_CSV}")
        return
    id_df = pd.read_csv(ID_RESULTS_CSV)
    id_df['Subject'] = id_df['Subject'].astype(str)
    
    # 2. Calculate behavioral metrics for all subjects
    subject_list = id_df['Subject'].unique()
    behavioral_data = [calculate_behavioral_metrics_for_subject(sub) for sub in subject_list]
    behavioral_df = pd.DataFrame([b for b in behavioral_data if b is not None])
    behavioral_df['Subject'] = behavioral_df['Subject'].astype(str)

    # 3. Merge the neural and behavioral dataframes
    merged_df = pd.merge(id_df, behavioral_df, on="Subject")
    if merged_df.empty:
        print("Merging failed or resulted in an empty dataframe. Check subject IDs.")
        return
    print(f"Successfully created master dataframe for {merged_df['Subject'].nunique()} subjects.")
    
    # 4. Loop through all combinations and run correlations
    all_correlations = []
    
    for task_phase in tqdm(TASK_PHASES_TO_ANALYZE, desc="Processing Task Phases"):
        for roi in ROIS_TO_ANALYZE:
            for metric in BEHAVIORAL_METRICS:
                
                # Subset the data for the current combination
                subset_df = merged_df[
                    (merged_df['Condition'] == task_phase) &
                    (merged_df['ROI'] == roi)
                ]
                
                if subset_df.empty or subset_df['Intrinsic_Dim'].isnull().any() or subset_df[metric].isnull().any():
                    continue

                # Calculate Pearson correlation
                r_val, p_val = pearsonr(subset_df['Intrinsic_Dim'], subset_df[metric])
                
                all_correlations.append({
                    "Task_Phase": task_phase,
                    "ROI": roi,
                    "Behavioral_Metric": metric,
                    "r_value": r_val,
                    "p_value": p_val
                })

                # 5. Generate individual scatter plot ONLY if the correlation is significant
                if p_val < SIGNIFICANCE_THRESHOLD:
                    print(f"Found significant correlation: {task_phase}/{roi} ID vs {metric} (r={r_val:.3f}, p={p_val:.3f})")
                    plt.figure(figsize=(7, 6))
                    sns.regplot(data=subset_df, x='Intrinsic_Dim', y=metric)
                    title = f"{roi} ID during {task_phase} vs. {metric.replace('_', ' ')}\n(r={r_val:.3f}, p={p_val:.3f})"
                    plt.title(title)
                    plt.xlabel(f"Intrinsic Dimensionality")
                    plt.ylabel(f"Proportion ({metric.replace('_', ' ')})")
                    plt.tight_layout()
                    plot_path = os.path.join(OUTPUT_DIR, f"scatter_{task_phase}_{roi}_{metric}.png")
                    plt.savefig(plot_path, dpi=300)
                    plt.close()

    # 6. Create and save the summary dataframe and heatmaps
    summary_df = pd.DataFrame(all_correlations)
    summary_path = os.path.join(OUTPUT_DIR, "all_correlations_summary.csv")
    summary_df.to_csv(summary_path, index=False)
    print(f"\nFull correlation summary saved to: {summary_path}")

    # Generate a heatmap for each behavioral metric
    for metric in BEHAVIORAL_METRICS:
        metric_df = summary_df[summary_df['Behavioral_Metric'] == metric]
        
        # Pivot for heatmap (r-values)
        pivot_r = metric_df.pivot(index="ROI", columns="Task_Phase", values="r_value")
        pivot_r = pivot_r.reindex(index=ROIS_TO_ANALYZE, columns=TASK_PHASES_TO_ANALYZE) # Ensure correct order
        
        # Pivot for heatmap (p-values for annotation)
        pivot_p = metric_df.pivot(index="ROI", columns="Task_Phase", values="p_value")
        pivot_p = pivot_p.reindex(index=ROIS_TO_ANALYZE, columns=TASK_PHASES_TO_ANALYZE)
        
        # Create annotations (asterisks for significance)
        annot = pivot_p.applymap(lambda p: "*" if p < SIGNIFICANCE_THRESHOLD else "")

        plt.figure(figsize=(10, 8))
        sns.heatmap(
            pivot_r,
            annot=annot,
            fmt='s', # Format as string
            cmap='vlag', # Diverging colormap (blue-white-red)
            center=0,
            linewidths=.5,
            cbar_kws={'label': "Pearson's r"}
        )
        plt.title(f"Correlation (r-value) between ID and {metric.replace('_', ' ')}")
        plt.ylabel("Region of Interest (ROI)")
        plt.xlabel("Task Phase")
        heatmap_path = os.path.join(OUTPUT_DIR, f"heatmap_correlation_{metric}.png")
        plt.savefig(heatmap_path, dpi=300, bbox_inches='tight')
        plt.close()
        print(f"Heatmap for {metric} saved to: {heatmap_path}")

if __name__ == '__main__':
    main()
